import clientDetails from "../db/models/clientDetails";
import User from "../db/models/user";
import clientAccountHandlers from "../db/models/clientAccountHandlers";
import { MondayService } from "../liberaries/Monday/mondayLib";
import clientAccountLogs from "../db/models/clientAccountLogs";
import logger from "../utils/logger";
import {triggerEmailNotification} from "../services/emailService"; 
import {noFoundClientTemplate} from "../emailTemplates/mondayClientSync"; 

export const activeClientListFetch = async (req, res) => {
	try {
        var results                  = [];
        const notFoundClients        = [];
        let validClientsInfo: any[]  = [];
        let validHandlersInfo: any[] = [];
		const monday               = new MondayService();
		const activeClientResponse = await monday.mondayClientList();
        // const activeClientResponse = mondayData();
        const clientsList = await clientDetails.find({status:"active"}).select("name").lean();

        const detailFields = {
            start_date: "date1__1",
            termination_date: "date__1",
            website_url:"text",
        };

        const accountHandlerFields = {
            am_id: "project_manager4",
            assoc_am_id: "dropdown_mkvf9s13",
            past_am_id: "dropdown_mkyqwh01",
            design_lead_id:"design_lead4",
            assoc_affiliate_lead_id:"dropdown8",
            paid_social_id:"text58",
            assoc_paid_social_id:"dropdown3",
            paid_search_id:"dup__of_paid_social_lead",
            assoc_paid_search_id:"dropdown78",
            email_lead_id:"dropdown30",
            assoc_email_lead_id:"dup__of_email_lead",
        };

        for(const client of clientsList){
            const clientId   = client?._id;
            const clientName = client?.name;
            const mondayClient = activeClientResponse.find(c =>
                c.clientName.toLowerCase().includes(clientName.toLowerCase())
            ) || null;
            if(mondayClient){
                const mondayData = mondayClient?.columns || [];

                /**client details**/
                validClientsInfo.push({
                    clientId,
                    ...Object.fromEntries(
                        Object.entries(detailFields).map(([key, id]) => [
                            key,
                            getTextById(mondayData, id)
                        ])
                    )
                });

                /**for account handlers **/
                validHandlersInfo.push({
                    clientId,
                    ...Object.fromEntries(
                        Object.entries(accountHandlerFields).map(([key, id]) => [
                            key,
                            getTextById(mondayData, id)
                        ])
                    )
                });
            }else{
                notFoundClients.push({clientId:clientId,clientName:clientName});
            }
        }

        results = await Promise.allSettled([
            updateClientInfo(validClientsInfo),
            updateAccountHandlerInfo(validHandlersInfo),
            sendEmailNotification(notFoundClients)
        ]);

        results.forEach((result, index) => {
            if (result.status === "rejected") {
                console.error(`Operation ${index} failed:`, result.reason);
            }
        });
		res.status(200).json({ status_code: 200, success: true, message: 'Monday API fetched successfully.', data: results });
	} catch (error) {
		res.status(422).json({ status_code: 422, success: false, message: 'Error in Monday API.', data: error });
	}
}

/**fetch values based on ID */
const getTextById = (arr, id) =>
    arr.find(x => x.id === id)?.text ?? null

async function fetchUsersIds(userRecords) {
    try{
        const usersRaw = await User.find({status:"active"}).select("first_name").lean();
        const userMap  = new Map<string, any>();
        usersRaw.forEach(u => {
            if (!u.first_name) return;

            userMap.set(
                u.first_name.toLowerCase().trim(),
                u._id
            );
        });

        return userRecords.map(record => {
            const updatedRecord: any = { clientId: record.clientId };

            Object.entries(record).forEach(([key, value]) => {

            if (key === "clientId") return;

            if (!value || typeof value !== "string") {
                updatedRecord[key] = [];
                return;
            }

            const names = value
                .split(",")
                .map(n => n.trim().toLowerCase())
                .filter(Boolean);
            
            const ids = names
                .map(name => userMap.get(name))
                .filter(Boolean);
            // console.log("ids==>",ids)
            updatedRecord[key] =
                ids.length === 0 ? [] :
                ids.length === 1 ? [ids[0]] :
                ids;
                // console.log(`${key}==>`,updatedRecord[key])
            });
            return updatedRecord;
        });
    }catch(error){
        logger.error(error,"error:");
    }
}

