async function updateClientInfo(updates){
    const operations = updates.map(({ clientId, ...updatePayload }) => ({
            updateOne: {
                filter: {
                _id: clientId 
                },
    
                update: {
                $set: updatePayload
                }
            }
        }));
    try{
        const ab =await clientDetails.bulkWrite(operations, { ordered: false });
    }catch(error){
        logger.error(error,`mongoDB error in ${clientDetails}: `);
    }
    return true;
}

async function updateAccountHandlerInfo(updates){
    updates = await fetchUsersIds(updates);
    const changedClientIds = await checkForHandlersChange(updates);
    const operations = updates.map(({ clientId, ...updatePayload }) => ({
            updateOne: {
                    filter: {
                    client_id: clientId 
                },
                update: {
                    $set: updatePayload
                }
            }
        }));

         try{
            // logger.info(operations,"operations");
            await clientAccountHandlers.bulkWrite(operations, { ordered: false });
            await createLogs(changedClientIds);
        }catch(error:any){
            logger.error(error,`mongoDB error in ${clientAccountHandlers}: `);
        }
        return true;
}

async function checkForHandlersChange(updates){
    const ids = updates.map(u => u.clientId);
    const existingDocs = await clientAccountHandlers.find(
        { client_id: { $in: ids } },
        {},
        { lean: true } 
    );
    const existingMap = new Map(
        existingDocs.map(doc => [doc.client_id.toString(), doc])
    );
    
    const changedClientIds = [];
    for (const { clientId, ...updatePayload } of updates) {
        const oldDoc = existingMap.get(clientId.toString());
        if (!oldDoc) continue;
        const hasChange = Object.keys(updatePayload).some(key => {
            const oldVal = (oldDoc[key] || []).map(id => id.toString()).sort();
            const newVal = (updatePayload[key] || []).map(id => id.toString()).sort();
            return JSON.stringify(oldVal) !== JSON.stringify(newVal);
        });
        if (hasChange) {
            changedClientIds.push(clientId);
        }
    }
    return changedClientIds;
}

async function createLogs(changedClientIds){
    // console.log("changedClientIds==>",changedClientIds);
    if(changedClientIds?.length){
        const changedClientsList = await clientDetails.aggregate([
        {
            $match: {
                _id: { $in: changedClientIds }     
            }
        },
        {
            $lookup: {
                from: "client_account_handlers",    
                localField: "_id",
                foreignField: "client_id",
                pipeline: [
                    {
                        $project: {
                            am_id: 1,
                            assoc_am_id: 1,
                            past_am_id: 1,
                            paid_social_id: 1,
                            assoc_paid_social_id: 1,
                            paid_search_id: 1,
                            assoc_paid_search_id: 1,
                            design_lead_id: 1,
                            assoc_design_lead_id: 1,
                            email_lead_id: 1,
                            assoc_email_lead_id: 1,
                            affiliate_lead_id: 1,
                            assoc_affiliate_lead_id: 1,
                        }
                    }
                ],
                as: "accountHandlers"
            }
        },
        {
            $unwind: {
                path: "$accountHandlers",
                preserveNullAndEmptyArrays: true
            }
        },
        {
            $project: {
                _id: 1,
                type: 1,
                status: 1,
                accountHandlers: 1            
            }
        }

    ]);

    // console.log("changedClientsList==>",changedClientsList);
    const operations = changedClientsList.map((payload) => {
        const start = new Date();
        start.setUTCHours(0, 0, 0, 0);

        const end = new Date();
        end.setUTCHours(23, 59, 59, 999);

        let updatedPayload = {
            client_id : payload._id,
            type      : payload.type,
            status    : payload.status,
            am_id     : payload.accountHandlers.am_id,
            assoc_am_id : payload.accountHandlers.assoc_am_id,
            past_am_id : payload.accountHandlers.past_am_id,
            paid_social_id : payload.accountHandlers.paid_social_id,
            assoc_paid_social_id : payload.accountHandlers.assoc_paid_social_id,
            paid_search_id : payload.accountHandlers.paid_search_id,
            assoc_paid_search_id : payload.accountHandlers.assoc_paid_search_id,
            design_lead_id : payload.accountHandlers.design_lead_id,
            assoc_design_lead_id : payload.accountHandlers.assoc_design_lead_id,
            email_lead_id : payload.accountHandlers.email_lead_id,
            affiliate_lead_id : payload.accountHandlers.affiliate_lead_id,
            assoc_affiliate_lead_id : payload.accountHandlers.assoc_affiliate_lead_id,
        }
        return {
            updateOne: {
                filter: { 
                    client_id: updatedPayload.client_id,  
                    createdAt: { $gte: start, $lte: end }
                },
                update: { $set: updatedPayload },
                upsert: true
            }
        };
    });
        // logger.info(operations,"operations");
        try{
           await clientAccountLogs.bulkWrite(operations, { ordered: false });
        }catch(error){
            logger.error(error,"error:")
        }   
    }
    return true;
}

async function sendEmailNotification(dataRecords){
    try{
        if(!dataRecords.length) return true;
        const recepient = "ankit@group8a.com";
        const subject   = "Important: (New Portal) Monday Data Sync";
        const content   = noFoundClientTemplate(dataRecords);
        await triggerEmailNotification(recepient,subject,content);
        return true;
    }catch(error){
        logger.error(error,"Active client list sync EmailNotification error: ");
    }
}